//! Output parity between the voice polish in `voxr_narrate` and the
//! JavaScript it ports.
//!
//! The fixture (`tests/fixtures/narration_polish_oracle.json`) was
//! generated by `tests/tools/narration_oracle/polish_oracle.mjs` over the
//! cases in `polish_cases.mjs` beside it, which `common::polish_cases`
//! lists in the same order and `common::signals` builds bit for bit. Each
//! case holds the FNV-1a hash of its input, the hashes of every output's
//! samples, the hash of the 16-bit data polish writes, and every number as
//! `String(x)`: all compare exactly.
//!
//! The reference cases (`common::polish_cases::reference_cases`) compare the
//! breath runs, the number of shelves and every output's samples exactly.
//! The band levels and the shelf run through a filter that normalizes its
//! coefficients where the JavaScript divides each sum, so a level, a
//! shortfall or a shelf gain may differ by up to 1e-9 dB.

use std::path::Path;

use serde::Deserialize;
use voxr_narrate::{self as narration, CompressorOptions, Span};

mod common;
use common::polish_cases::{
    PolishCase, ReferenceCase, pcm16_values, polish_cases, reference_cases,
};
use common::signals;
use common::{assert_oracle_current, check, load_json, num};

const FIXTURE: &str = concat!(
    env!("CARGO_MANIFEST_DIR"),
    "/tests/fixtures/narration_polish_oracle.json"
);
const ORACLE: &str = concat!(
    env!("CARGO_MANIFEST_DIR"),
    "/tests/tools/narration_oracle/polish_oracle.mjs"
);

#[derive(Debug, Deserialize)]
struct Fixture {
    cases: Vec<Case>,
    pcm16: Pcm16,
    reference: Vec<RefCase>,
}

#[derive(Debug, Deserialize)]
#[serde(rename_all = "camelCase")]
struct Case {
    name: String,
    rate: u32,
    n: usize,
    input: String,
    compress: String,
    compress_options: Option<String>,
    de_ess: DeEssOut,
    normalize: String,
    normalize_minus6: String,
    levels: Option<Vec<Option<String>>>,
    polish: Option<PolishOut>,
}

/// A stats field JavaScript never set is `null`.
#[derive(Debug, Deserialize)]
struct DeEssOut {
    samples: String,
    share: Option<String>,
    deepest: Option<String>,
}

#[derive(Debug, Deserialize)]
struct PolishOut {
    leveled: String,
    samples: String,
    pcm16: String,
    stats: PolishStats,
}

#[derive(Debug, Deserialize)]
#[serde(rename_all = "camelCase")]
struct PolishStats {
    leveled: usize,
    max_gain: String,
    ess_share: String,
    ess_deepest: String,
}

#[derive(Debug, Deserialize)]
struct Pcm16 {
    values: Vec<String>,
    ints: Vec<i16>,
}

#[derive(Debug, Deserialize)]
struct RefCase {
    name: String,
    rate: u32,
    n: usize,
    input: String,
    breaths: BreathsOut,
    bass: BassOut,
    prepare: PrepareOut,
}

#[derive(Debug, Deserialize)]
struct BreathsOut {
    samples: String,
    runs: Vec<(usize, usize)>,
    count: usize,
}

#[derive(Debug, Deserialize)]
struct BassOut {
    balance: String,
    shorts: Vec<String>,
    steps: Vec<String>,
    gain: String,
    samples: String,
}

#[derive(Debug, Deserialize)]
struct PrepareOut {
    samples: String,
    shelves: usize,
}

/// The most a level, a shortfall or a shelf gain may differ, in dB.
const DB_TOLERANCE: f64 = 1e-9;

/// A number as `{:?}`, so the exact doubles compare as text.
fn exact(v: f64) -> String {
    format!("{v:?}")
}

/// Every difference between the port and the fixture on one case.
fn differences(case: &PolishCase, want: &Case) -> Vec<String> {
    let mut diffs = Vec::new();
    let x = signals::render(case.n, &case.ops);
    let input = signals::fnv1a(&x);
    if input != want.input {
        return vec![format!(
            "input signal differs from the oracle's: hash {input}, want {}",
            want.input
        )];
    }
    if case.compress.is_some() != want.compress_options.is_some()
        || case.spans.is_some() != want.levels.is_some()
        || case.spans.is_some() != want.polish.is_some()
    {
        return vec![
            "compressor settings, spans, levels or polish listed on one side only".to_string(),
        ];
    }
    let rate = case.rate;
    let compressed = narration::compress_voice(&x, rate, CompressorOptions::default());
    check(
        &mut diffs,
        "compressVoice",
        signals::fnv1a(&compressed),
        want.compress.clone(),
    );
    if let (Some(options), Some(hash)) = (case.compress, &want.compress_options) {
        check(
            &mut diffs,
            "compressVoice with options",
            signals::fnv1a(&narration::compress_voice(&x, rate, options)),
            hash.clone(),
        );
    }
    let (de_essed, stats) = narration::de_ess(&x, rate);
    check(
        &mut diffs,
        "deEss samples",
        signals::fnv1a(&de_essed),
        want.de_ess.samples.clone(),
    );
    // With no vowel energy JavaScript leaves its stats unset, and polish
    // reads them as 0.
    let unset = |v: &Option<String>| exact(v.as_deref().map_or(0.0, num));
    check(
        &mut diffs,
        "deEss share",
        exact(stats.share),
        unset(&want.de_ess.share),
    );
    check(
        &mut diffs,
        "deEss deepest",
        exact(stats.deepest),
        unset(&want.de_ess.deepest),
    );
    check(
        &mut diffs,
        "normalizePeak",
        signals::fnv1a(&narration::normalize_peak(&x, -1.0)),
        want.normalize.clone(),
    );
    check(
        &mut diffs,
        "normalizePeak at -6 dB",
        signals::fnv1a(&narration::normalize_peak(&x, -6.0)),
        want.normalize_minus6.clone(),
    );
    let (Some(spans), Some(levels), Some(p)) = (&case.spans, &want.levels, &want.polish) else {
        return diffs;
    };
    let spans: Vec<Span> = spans
        .iter()
        .map(|&(start, end)| Span { start, end })
        .collect();
    let got: Vec<Option<String>> = spans
        .iter()
        .map(|s| narration::speech_level(&x, s.start, s.end, rate).map(exact))
        .collect();
    let expected: Vec<Option<String>> = levels
        .iter()
        .map(|l| l.as_deref().map(|t| exact(num(t))))
        .collect();
    check(
        &mut diffs,
        "speechLevel",
        format!("{got:?}"),
        format!("{expected:?}"),
    );
    let mut leveled = x.clone();
    let level = narration::even_levels(&mut leveled, &spans, rate);
    check(
        &mut diffs,
        "polish after leveling",
        signals::fnv1a(&leveled),
        p.leveled.clone(),
    );
    let mut polished = x.clone();
    let report = narration::polish(&mut polished, &spans, rate);
    check(
        &mut diffs,
        "polish samples",
        signals::fnv1a(&polished),
        p.samples.clone(),
    );
    let bytes: Vec<u8> = narration::pcm16_like_js(&polished)
        .iter()
        .flat_map(|v| v.to_le_bytes())
        .collect();
    check(
        &mut diffs,
        "polish 16-bit data",
        signals::fnv1a_bytes(&bytes),
        p.pcm16.clone(),
    );
    check(
        &mut diffs,
        "even_levels leveled",
        level.leveled.to_string(),
        p.stats.leveled.to_string(),
    );
    check(
        &mut diffs,
        "polish leveled",
        report.leveled.to_string(),
        p.stats.leveled.to_string(),
    );
    check(
        &mut diffs,
        "polish maxGain",
        exact(report.max_gain_db),
        exact(num(&p.stats.max_gain)),
    );
    check(
        &mut diffs,
        "polish essShare",
        exact(report.ess_share),
        exact(num(&p.stats.ess_share)),
    );
    check(
        &mut diffs,
        "polish essDeepest",
        exact(report.ess_deepest_db),
        exact(num(&p.stats.ess_deepest)),
    );
    diffs
}

/// Records a level that differs from the fixture's by more than
/// [`DB_TOLERANCE`], and tracks the largest difference in `worst`.
fn check_db(diffs: &mut Vec<String>, worst: &mut f64, what: &str, got: f64, want: &str) {
    let want = num(want);
    let d = (got - want).abs();
    *worst = worst.max(d);
    if d > DB_TOLERANCE || d.is_nan() {
        diffs.push(format!("{what}: got {got:?}, want {want:?}"));
    }
}

/// Every difference between the reference preparation and the fixture on
/// one case.
fn reference_differences(case: &ReferenceCase, want: &RefCase, worst: &mut f64) -> Vec<String> {
    let mut diffs = Vec::new();
    let x = signals::render(case.n, &case.ops);
    let input = signals::fnv1a(&x);
    if input != want.input {
        return vec![format!(
            "input signal differs from the oracle's: hash {input}, want {}",
            want.input
        )];
    }
    let rate = case.rate;
    let (quiet, breaths) = narration::quiet_breaths(&x, rate);
    check(
        &mut diffs,
        "quietBreaths samples",
        signals::fnv1a(&quiet),
        want.breaths.samples.clone(),
    );
    let runs: Vec<(usize, usize)> = breaths.runs.iter().map(|r| (r.start, r.end)).collect();
    check(
        &mut diffs,
        "breathRuns",
        format!("{runs:?}"),
        format!("{:?}", want.breaths.runs),
    );
    check(
        &mut diffs,
        "quietBreaths runs",
        breaths.runs.len().to_string(),
        want.breaths.count.to_string(),
    );
    check_db(
        &mut diffs,
        worst,
        "bassBalance",
        narration::bass_balance(&x, rate),
        &want.bass.balance,
    );
    let (lifted, bass) = narration::lift_bass(&x, rate);
    check(
        &mut diffs,
        "liftBass shortfalls measured",
        bass.shorts.len().to_string(),
        want.bass.shorts.len().to_string(),
    );
    check(
        &mut diffs,
        "liftBass shelves",
        bass.steps.len().to_string(),
        want.bass.steps.len().to_string(),
    );
    for (i, (got, w)) in bass.shorts.iter().zip(&want.bass.shorts).enumerate() {
        check_db(
            &mut diffs,
            worst,
            &format!("liftBass shortfall {i}"),
            *got,
            w,
        );
    }
    for (i, (got, w)) in bass.steps.iter().zip(&want.bass.steps).enumerate() {
        check_db(&mut diffs, worst, &format!("liftBass shelf {i}"), *got, w);
    }
    check_db(
        &mut diffs,
        worst,
        "liftBass gain",
        bass.gain,
        &want.bass.gain,
    );
    check(
        &mut diffs,
        "liftBass samples",
        signals::fnv1a(&lifted),
        want.bass.samples.clone(),
    );
    let (_, shelved) = narration::lift_bass(&quiet, rate);
    check(
        &mut diffs,
        "prepareReference shelves",
        shelved.steps.len().to_string(),
        want.prepare.shelves.to_string(),
    );
    check(
        &mut diffs,
        "prepareReference samples",
        signals::fnv1a(&narration::prepare_reference(&x, rate).0),
        want.prepare.samples.clone(),
    );
    diffs
}

#[test]
fn reference_preparation_matches_javascript_on_every_signal() {
    let fixture: Fixture = load_json(Path::new(FIXTURE));
    let cases = reference_cases();
    let ours: Vec<(&str, u32, usize)> = cases.iter().map(|c| (c.name, c.rate, c.n)).collect();
    let theirs: Vec<(&str, u32, usize)> = fixture
        .reference
        .iter()
        .map(|c| (c.name.as_str(), c.rate, c.n))
        .collect();
    assert_eq!(
        ours, theirs,
        "common::polish_cases::reference_cases and REFERENCE_CASES list different cases"
    );
    let mut worst = 0.0f64;
    let mut failures = Vec::new();
    for (case, want) in cases.iter().zip(&fixture.reference) {
        for d in reference_differences(case, want, &mut worst) {
            failures.push(format!("{}: {d}", case.name));
        }
    }
    eprintln!("reference preparation: largest level difference {worst:e} dB");
    assert!(
        failures.is_empty(),
        "{} differences over {} signals:\n{}",
        failures.len(),
        cases.len(),
        failures.join("\n")
    );
}

#[test]
fn polish_matches_javascript_on_every_signal() {
    let fixture: Fixture = load_json(Path::new(FIXTURE));
    let cases = polish_cases();
    let ours: Vec<(&str, u32, usize)> = cases.iter().map(|c| (c.name, c.rate, c.n)).collect();
    let theirs: Vec<(&str, u32, usize)> = fixture
        .cases
        .iter()
        .map(|c| (c.name.as_str(), c.rate, c.n))
        .collect();
    assert_eq!(
        ours, theirs,
        "common::polish_cases and polish_cases.mjs list different cases"
    );
    let failures: Vec<String> = cases
        .iter()
        .zip(&fixture.cases)
        .flat_map(|(case, want)| {
            differences(case, want)
                .into_iter()
                .map(move |d| format!("{}: {d}", case.name))
        })
        .collect();
    assert!(
        failures.is_empty(),
        "{} differences over {} signals:\n{}",
        failures.len(),
        cases.len(),
        failures.join("\n")
    );
}

#[test]
fn pcm16_matches_javascript() {
    let fixture: Fixture = load_json(Path::new(FIXTURE));
    let values = pcm16_values();
    let listed: Vec<f64> = fixture.pcm16.values.iter().map(|v| num(v)).collect();
    let ours: Vec<f64> = values.iter().map(|&v| f64::from(v)).collect();
    assert_eq!(ours, listed, "pcm16_values and PCM16_VALUES differ");
    assert_eq!(narration::pcm16_like_js(&values), fixture.pcm16.ints);
}

/// The oracle also needs `ffmpeg` on PATH: the JavaScript polish reads its
/// take through it.
#[test]
fn polish_oracle_fixture_is_current() {
    assert_oracle_current(ORACLE, FIXTURE);
}
